private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("size must be non-negative");
    }
    if (size == 0) {
        return;
    }
    if (buffer == null) {
        buffer = new byte[size];
        return;
    }
    int currentCapacity = buffer.length;
    long newCapLong = (long) currentCapacity * 2;
    long required = (long) currentCapacity + size;
    long newCap = Math.max(newCapLong, required);
    if (newCap > Integer.MAX_VALUE) {
        newCap = Integer.MAX_VALUE;
    }
    if (newCap <= currentCapacity) {
        throw new OutOfMemoryError("Cannot enlarge buffer");
    }
    byte[] newBuffer = new byte[(int) newCap];
    System.arraycopy(buffer, 0, newBuffer, 0, currentCapacity);
    buffer = newBuffer;
}

