public static int nullSafeHashCode(long[] array){
    if (array == null) {
        return 0;
    }
    int result = 1;
    for (long value : array) {
        int elementHash = (int)(value ^ (value >>> 32));
        result = 31 * result + elementHash;
    }
    return result;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    // Handle null or no left child
    if (node == null || node.left == null) {
        return node;
    }
    try {
        TreeNode<T> leftChild = node.left;
        TreeNode<T> leftRightSubtree = leftChild.right;

        // Perform rotation
        leftChild.right = node;
        node.left = leftRightSubtree;

        // Update parent references
        leftChild.parent = node.parent;
        node.parent = leftChild;
        if (leftRightSubtree != null) {
            leftRightSubtree.parent = node;
        }

        // Update the old parent to point to the new root
        if (leftChild.parent != null) {
            if (leftChild.parent.left == node) {
                leftChild.parent.left = leftChild;
            } else if (leftChild.parent.right == node) {
                leftChild.parent.right = leftChild;
            }
        }

        return leftChild;
    } catch (Exception e) {
        // In case of any unexpected runtime issue, rethrow as unchecked
        throw new RuntimeException("Error during right rotation", e);
    }
}

