public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    try {
        StringBuilder sb = new StringBuilder();
        // Timestamp
        long ts = event.getTimeStamp();
        sb.append(new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                .format(new java.util.Date(ts)));
        sb.append(" [");
        String threadName = event.getThreadName();
        sb.append(threadName != null ? threadName : "unknown");
        sb.append("] ");
        // Level
        Object levelObj = event.getLevel();
        sb.append(levelObj != null ? levelObj.toString() : "UNKNOWN");
        sb.append(" ");
        // Logger name
        String loggerName = event.getLoggerName();
        sb.append(loggerName != null ? loggerName : "unknown");
        sb.append(" - ");
        // Message
        String message = event.getFormattedMessage();
        sb.append(message != null ? message : "");
        // Throwable (if available)
        Object throwableInfoObj = event.getThrowableInformation();
        if (throwableInfoObj != null) {
            try {
                java.lang.reflect.Method getThrowableMethod =
                        throwableInfoObj.getClass().getMethod("getThrowable");
                Throwable t = (Throwable) getThrowableMethod.invoke(throwableInfoObj);
                if (t != null) {
                    sb.append(System.lineSeparator());
                    sb.append(t.toString());
                    for (StackTraceElement ste : t.getStackTrace()) {
                        sb.append(System.lineSeparator());
                        sb.append("\tat ").append(ste.toString());
                    }
                }
            } catch (Exception e) {
                // Ignore throwable formatting errors
            }
        }
        return sb.toString();
    } catch (Exception e) {
        // Fallback to simple formatted message
        try {
            return event.getFormattedMessage();
        } catch (Exception ex) {
            return "";
        }
    }
}

