        throw new IllegalArgumentException("Partition sizes must be positive");
    }
    try {
        // Create left partition vertices
        for (int i = 0; i < m; i++) {
            V v = target.addVertex();
            resultMap.put("left" + i, v);
        }
        // Create right partition vertices
        for (int i = 0; i < n; i++) {
            V v = target.addVertex();
            resultMap.put("right" + i, v);
        }
        // Add edges between every left and right vertex
        for (int i = 0; i < m; i++) {
            V left = resultMap.get("left" + i);
            for (int j = 0; j < n; j++) {
