    }
}

protected int findByte(byte value, int pos) {
    // Ensure the buffer exists
    if (buffer == null) {
        throw new IllegalStateException("Buffer is null");
    }
    // Validate starting position
    if (pos < 0 || pos >= buffer.length) {
        return -1;
    }
    // Search for the byte starting from pos
    for (int i = pos; i < buffer.length; i++) {
        if (buffer[i] == value) {
            return i;
        }
    }
    // Not found
    return -1;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    int size;
    try {
        size = schema.getSerializedSize(message);
    } catch (Exception e) {
        throw new IOException("Failed to compute serialized size", e);
    }
    // Write length prefix as varint
    int temp = size;
    while ((temp & ~0x7F) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
    out.write(temp);
    // Write message
    try {
        schema.writeTo(message, out);
    } catch (Exception e) {
        throw new IOException("Failed to serialize message", e);
    }
    return size;
}

