public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    try {
        java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> typeVarMap = buildTypeVariableMap(targetType);
        if (genericType instanceof java.lang.reflect.ParameterizedType) {
            java.lang.reflect.ParameterizedType pt = (java.lang.reflect.ParameterizedType) genericType;
            java.lang.reflect.Type[] args = pt.getActualTypeArguments();
            Class<?>[] result = new Class<?>[args.length];
            for (int i = 0; i < args.length; i++) {
                Class<?> resolved = resolveType(args[i], typeVarMap);
                if (resolved == null) {
                    return null;
                }
                result[i] = resolved;
            }
            return result;
        } else if (genericType instanceof java.lang.reflect.TypeVariable) {
            Class<?> resolved = resolveType(genericType, typeVarMap);
            if (resolved == null) {
                return null;
            }
            return new Class<?>[]{resolved};
        } else if (genericType instanceof java.lang.reflect.GenericArrayType) {
            java.lang.reflect.GenericArrayType gat = (java.lang.reflect.GenericArrayType) genericType;
            Class<?> component = resolveType(gat.getGenericComponentType(), typeVarMap);
            if (component == null) {
                return null;
            }
            Class<?> arrayClass = java.lang.reflect.Array.newInstance(component, 0).getClass();
            return new Class<?>[]{arrayClass};
        } else if (genericType instanceof Class) {
            // raw type, cannot resolve
            return null;
        } else {
            return null;
        }
    } catch (Exception e) {
        return null;
    }
}

private static java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> buildTypeVariableMap(Class<?> clazz) {
    java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> map = new java.util.HashMap<>();
    // superclass
    java.lang.reflect.Type genericSuper = clazz.getGenericSuperclass();
    if (genericSuper != null) {
        if (genericSuper instanceof java.lang.reflect.ParameterizedType) {
            java.lang.reflect.ParameterizedType pt = (java.lang.reflect.ParameterizedType) genericSuper;
            Class<?> superClass = (Class<?>) pt.getRawType();
            java.lang.reflect.TypeVariable<?>[] vars = superClass.getTypeParameters();
            java.lang.reflect.Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
            map.putAll(buildTypeVariableMap(superClass));
        } else if (genericSuper instanceof Class) {
            map.putAll(buildTypeVariableMap((Class<?>) genericSuper));
        }
    }
    // interfaces
    for (java.lang.reflect.Type genericInterface : clazz.getGenericInterfaces()) {
        if (genericInterface instanceof java.lang.reflect.ParameterizedType) {
            java.lang.reflect.ParameterizedType pt = (java.lang.reflect.ParameterizedType) genericInterface;
            Class<?> iface = (Class<?>) pt.getRawType();
            java.lang.reflect.TypeVariable<?>[] vars = iface.getTypeParameters();
            java.lang.reflect.Type[] args = pt.getActualTypeArguments();
            for (int i = 0; i < vars.length; i++) {
                map.put(vars[i], args[i]);
            }
            map.putAll(buildTypeVariableMap(iface));
        } else if (genericInterface instanceof Class) {
            map.putAll(buildTypeVariableMap((Class<?>) genericInterface));
        }
    }
    return map;
}

private static Class<?> resolveType(java.lang.reflect.Type type, java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> map) {
    if (type instanceof Class) {
        return (Class<?>) type;
    } else if (type instanceof java.lang.reflect.TypeVariable) {
        java.lang.reflect.TypeVariable<?> tv = (java.lang.reflect.TypeVariable<?>) type;
        java.lang.reflect.Type resolved = map.get(tv);
        if (resolved == null) {
            return null;
        }
        return resolveType(resolved, map);
    } else if (type instanceof java.lang.reflect.ParameterizedType) {
        return (Class<?>) ((java.lang.reflect.ParameterizedType) type).getRawType();
    } else if (type instanceof java.lang.reflect.GenericArrayType) {
        java.lang.reflect.GenericArrayType gat = (java.lang.reflect.GenericArrayType) type;
        Class<?> component = resolveType(gat.getGenericComponentType(), map);
        if (component == null) {
            return null;
        }
        return java.lang.reflect.Array.newInstance(component, 0).getClass();
    } else if (type instanceof java.lang.reflect.WildcardType) {
        java.lang.reflect.WildcardType wt = (java.lang.reflect.WildcardType) type;
        java.lang.reflect.Type[] lower = wt.getLowerBounds();
        if (lower.length > 0) {
            return resolveType(lower[0], map);
        }
        java.lang.reflect.Type[] upper = wt.getUpperBounds();
        if (upper.length > 0) {
            return resolveType(upper[0], map);
        }
        return null;
    } else {
        return null;
    }
}

