public Mappings diffStructure(String tableName, Mappings mappings) {
    if (tableName == null || tableName.isEmpty() || mappings == null) {
        return new Mappings();
    }
    try {
        org.elasticsearch.client.indices.GetMappingsRequest getMappingsRequest =
                new org.elasticsearch.client.indices.GetMappingsRequest().indices(tableName);
        org.elasticsearch.client.indices.GetMappingsResponse getMappingsResponse =
                client.indices().getMapping(getMappingsRequest, org.elasticsearch.client.RequestOptions.DEFAULT);
        org.elasticsearch.cluster.metadata.MappingMetadata mappingMetadata =
                getMappingsResponse.mappings().get(tableName);
        if (mappingMetadata == null) {
            return new Mappings();
        }
        java.util.Map<String, Object> currentProps = mappingMetadata.getSourceAsMap();
        currentProps.remove("_source");
        java.util.Map<String, Object> inputProps = mappings.getSourceAsMap();
        java.util.Map<String, Object> diffProps = new java.util.HashMap<>();
        for (java.util.Map.Entry<String, Object> entry : currentProps.entrySet()) {
            if (!inputProps.containsKey(entry.getKey())) {
                diffProps.put(entry.getKey(), entry.getValue());
            }
        }
        return new Mappings(diffProps);
    } catch (Exception e) {
        return new Mappings();
    }
}

