            // Fallback to the current working directory if user.home is not available
            userHome = ".";
        }
        configDir = new java.io.File(userHome, "lf5");
    }

    try {
        if (!configDir.exists()) {
            if (!configDir.mkdirs()) {
                System.err.println("Failed to create configuration directory: " + configDir.getAbsolutePath());
            }
        } else if (!configDir.isDirectory()) {
            System.err.println("Configuration path exists but is not a directory: " + configDir.getAbsolutePath());
        } else if (!configDir.canWrite()) {
            System.err.println("Configuration directory is not writable: " + configDir.getAbsolutePath());
        }
    } catch (SecurityException se) {
        System.err.println("Security exception while creating configuration directory: " + se.getMessage());
        se.printStackTrace();
    } catch (Exception e) {
        System.err.println("Unexpected exception while creating configuration directory: " + e.getMessage());
        e.printStackTrace();
    }
}

public long readLong(final int offset){
    // Validate the offset to ensure we can read 8 bytes safely
    if (offset < 0 || offset + 8 > b.length) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }
    // Combine the 8 bytes into a signed long value (big-endian)
    return ((long)(b[offset]     & 0xFF) << 56) |
           ((long)(b[offset + 1] & 0xFF) << 48) |
           ((long)(b[offset + 2] & 0xFF) << 40) |
           ((long)(b[offset + 3] & 0xFF) << 32) |
           ((long)(b[offset + 4] & 0xFF) << 24) |
           ((long)(b[offset + 5] & 0xFF) << 16) |
           ((long)(b[offset + 6] & 0xFF) << 8)  |
           ((long)(b[offset + 7] & 0xFF));
}

