public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    if (clients == null) {
        return;
    }
    String telnetMessage = message + "\r\n";
    java.util.Iterator<java.net.Socket> it = clients.iterator();
    while (it.hasNext()) {
        java.net.Socket client = it.next();
        try {
            java.io.OutputStream out = client.getOutputStream();
            java.io.PrintWriter writer = new java.io.PrintWriter(out, true);
            writer.print(telnetMessage);
            writer.flush();
        } catch (java.io.IOException e) {
            System.err.println("Error sending message to client: " + e.getMessage());
            try {
                client.close();
            } catch (java.io.IOException ex) {
                // ignore
            }
            it.remove();
        }
    }
}

