static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    String str = Long.toString(timeBucket);
    if(str.length() != 8){
        throw new IllegalArgumentException("timeBucket must be in YYYYMMDD format");
    }
    int year, month, day;
    try{
        year = Integer.parseInt(str.substring(0,4));
        month = Integer.parseInt(str.substring(4,6));
        day = Integer.parseInt(str.substring(6,8));
    }catch(NumberFormatException e){
        throw new IllegalArgumentException("timeBucket contains non-numeric characters", e);
    }
    // Validate the date
    try{
        java.time.LocalDate.of(year, month, day);
    }catch(Exception e){
        throw new IllegalArgumentException("timeBucket is not a valid date", e);
    }
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index or length out of bounds");
    }
    int end = index + len;
    int size = 0;
    int i = index;
    try {
        while (i < end) {
            int cp = str.codePointAt(i);
            if (cp <= 0x7F) {
                size += 1;
            } else if (cp <= 0x7FF) {
                size += 2;
            } else if (cp <= 0xFFFF) {
                size += 3;
            } else {
                size += 4;
            }
            i += Character.charCount(cp);
        }
    } catch (Exception e) {
        throw new IllegalStateException("Error computing UTF-8 size", e);
    }
    return size;
}

