            if (edge == null) {
                continue;
            }
            V source = edge.getSource();
            V target = edge.getTarget();
            if (source != null) {
                visibleVertices.add(source);
            }
            if (target != null) {
                visibleVertices.add(target);
            }
        }
    } catch (Exception e) {
