public void removeFromTreeEdgeList() {
    // Remove this edge from the first vertex's tree edge list
    if (treeEdgePrev != null) {
        treeEdgePrev.treeEdgeNext = treeEdgeNext;
    } else if (from != null) {
        from.treeEdgeHead = treeEdgeNext;
    }
    if (treeEdgeNext != null) {
        treeEdgeNext.treeEdgePrev = treeEdgePrev;
    } else if (from != null) {
        from.treeEdgeTail = treeEdgePrev;
    }

    // Remove this edge from the second vertex's tree edge list
    if (treeEdgePrevOpposite != null) {
        treeEdgePrevOpposite.treeEdgeNextOpposite = treeEdgeNextOpposite;
    } else if (to != null) {
        to.treeEdgeHead = treeEdgeNextOpposite;
    }
    if (treeEdgeNextOpposite != null) {
        treeEdgeNextOpposite.treeEdgePrevOpposite = treeEdgePrevOpposite;
    } else if (to != null) {
        to.treeEdgeTail = treeEdgePrevOpposite;
    }

    // Nullify this edge's pointers to avoid dangling references
    treeEdgePrev = null;
    treeEdgeNext = null;
    treeEdgePrevOpposite = null;
    treeEdgeNextOpposite = null;
}

public static String findAndSubst(String key, Properties props){
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    try {
        java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)\\}");
        java.util.regex.Matcher matcher = pattern.matcher(value);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            String expr = matcher.group(1);
            String replacement;
            int colon = expr.indexOf(':');
            if (colon >= 0) {
                String varName = expr.substring(0, colon);
                String defaultVal = expr.substring(colon + 1);
                String propVal = props.getProperty(varName);
                replacement = (propVal != null) ? propVal : defaultVal;
            } else {
                String propVal = props.getProperty(expr);
                replacement = (propVal != null) ? propVal : "";
            }
            replacement = java.util.regex.Matcher.quoteReplacement(replacement);
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        return sb.toString();
    } catch (Exception e) {
        return null;
    }
}

