        return str.regionMatches(true, str.length() - suffix.length(), suffix, 0, suffix.length());
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return Collections.emptyList();
    }
    boolean isAbsolute = rawPath.startsWith("/");
    String[] parts = rawPath.split("/", -1);
    List<PathSegmentImpl> segments = new ArrayList<>(parts.length);
    int start = isAbsolute ? 1 : 0;
    for (int i = start; i < parts.length; i++) {
        String encoded = parts[i];
        String decoded = encoded;
        if (decode) {
            try {
                decoded = java.net.URLDecoder.decode(encoded, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(encoded, decoded));
    }
    return segments;
}

