private void pop(final String descriptor){
    if (descriptor == null) {
        throw new NullPointerException("Descriptor cannot be null");
    }
    int len = descriptor.length();
    if (len == 0) {
        throw new IllegalArgumentException("Empty descriptor");
    }
    int pos = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types only
        pos = 1;
        while (pos < len && descriptor.charAt(pos) != ')') {
            // Parse one argument type
            char c = descriptor.charAt(pos);
            if (c == '[') {
                // Array type: consume all '['
                while (pos < len && descriptor.charAt(pos) == '[') {
                    pos++;
                }
                if (pos >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                c = descriptor.charAt(pos);
                if (c == 'L') {
                    // Object type inside array
                    pos++;
                    while (pos < len && descriptor.charAt(pos) != ';') {
                        pos++;
                    }
                    if (pos >= len) {
                        throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                    }
                    pos++; // consume ';'
                } else {
                    // Primitive type inside array
                    pos++; // consume primitive
                }
            } else if (c == 'L') {
                // Object type
                pos++;
                while (pos < len && descriptor.charAt(pos) != ';') {
                    pos++;
                }
                if (pos >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                pos++; // consume ';'
            } else {
                // Primitive type
                pos++;
            }
            // Pop one type from the output stack
            if (outputStack.isEmpty()) {
                throw new IllegalStateException("Stack underflow while popping argument type");
            }
            outputStack.pop();
        }
        if (pos >= len || descriptor.charAt(pos) != ')') {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        pos++; // skip ')'
        if (pos >= len) {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        // Parse return type (ignored but validated)
        char c = descriptor.charAt(pos);
        if (c == '[') {
            while (pos < len && descriptor.charAt(pos) == '[') {
                pos++;
            }
            if (pos >= len) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            c = descriptor.charAt(pos);
            if (c == 'L') {
                pos++;
                while (pos < len && descriptor.charAt(pos) != ';') {
                    pos++;
                }
                if (pos >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                pos++;
            } else {
                pos++;
            }
        } else if (c == 'L') {
            pos++;
            while (pos < len && descriptor.charAt(pos) != ';') {
                pos++;
            }
            if (pos >= len) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            pos++;
        } else {
            pos++;
        }
        if (pos != len) {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
    } else {
        // Type descriptor: pop one type
        char c = descriptor.charAt(pos);
        if (c == '[') {
            while (pos < len && descriptor.charAt(pos) == '[') {
                pos++;
            }
            if (pos >= len) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            c = descriptor.charAt(pos);
            if (c == 'L') {
                pos++;
                while (pos < len && descriptor.charAt(pos) != ';') {
                    pos++;
                }
                if (pos >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                pos++;
            } else {
                pos++;
            }
        } else if (c == 'L') {
            pos++;
            while (pos < len && descriptor.charAt(pos) != ';') {
                pos++;
            }
            if (pos >= len) {
                throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
            }
            pos++;
        } else {
            pos++;
        }
        if (pos != len) {
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
        }
        if (outputStack.isEmpty()) {
            throw new IllegalStateException("Stack underflow while popping type");
        }
        outputStack.pop();
    }
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("b is null");
    }
    if (off < 0 || len < 0 || off > b.length - len) {
        throw new IndexOutOfBoundsException("offset or length out of bounds");
    }
    if (len == 0) {
        return;
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        int newCapacity = Math.max(buf.length << 1, newCount);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
