        throw new IndexOutOfBoundsException("Index out of bounds: i=" + i + ", j=" + j + ", length=" + arr.length);
    }
    if (i == j) {
        return; // nothing to do
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

