    Box2D right = new Box2D(midX, minY, maxX, maxY);
    return new Pair<>(left, right);
}

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("size must be non-negative");
    }
    // If no buffer exists yet, simply allocate the required capacity
    int currentCapacity = (data == null) ? 0 : data.length;
    int requiredCapacity = this.size + size;
    if (requiredCapacity <= currentCapacity) {
        return; // already enough space
    }
    // Compute new capacity, doubling the current capacity or using required capacity
    int newCapacity;
    if (currentCapacity > Integer.MAX_VALUE / 2) {
        newCapacity = Integer.MAX_VALUE;
    } else {
        newCapacity = currentCapacity * 2;
    }
    if (newCapacity < requiredCapacity) {
        newCapacity = requiredCapacity;
    }
    // Guard against overflow
    if (newCapacity < 0) {
        newCapacity = Integer.MAX_VALUE;
    }
    try {
        byte[] newData = new byte[newCapacity];
        if (data != null) {
            System.arraycopy(data, 0, newData, 0, this.size);
        }
        data = newData;
    } catch (OutOfMemoryError e) {
        throw new RuntimeException("Failed to enlarge byte vector", e);
    }
}

