@SuppressWarnings("unchecked") public static Supplier<String> createStringSupplier(int start){
    // Use an AtomicInteger for thread‑safe, incremental counter
    java.util.concurrent.atomic.AtomicInteger counter = new java.util.concurrent.atomic.AtomicInteger(start);
    return () -> {
        try {
            // Prevent integer overflow: if the next value would exceed Integer.MAX_VALUE,
            // throw an exception instead of returning a duplicate or negative number.
            if (counter.get() == Integer.MAX_VALUE) {
                throw new IllegalStateException("Integer overflow, cannot generate more unique strings");
            }
            int value = counter.getAndIncrement();
            return Integer.toString(value);
        } catch (Exception e) {
            // Wrap any unexpected exception in a RuntimeException to satisfy the Supplier contract
            throw new RuntimeException("Error generating unique string", e);
        }
    };
}

