private void putAbstractTypes(final int start, final int end) {
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end indices for currentFrame");
    }
    for (int i = start; i < end; i++) {
        VerificationType type = currentFrame[i];
        if (type == null) {
            throw new IllegalStateException("Null type encountered at index " + i);
        }
        byte tag = type.getTag();
        try {
            stackMapTableEntries.write(tag);
            switch (tag) {
                case 7: // object
                    int classIndex = type.getClassIndex();
                    stackMapTableEntries.write((classIndex >> 8) & 0xFF);
                    stackMapTableEntries.write(classIndex & 0xFF);
                    break;
                case 8: // uninitialized
                    int offset = type.getOffset();
                    stackMapTableEntries.write((offset >> 8) & 0xFF);
                    stackMapTableEntries.write(offset & 0xFF);
                    break;
                case 0: case 1: case 2: case 3: case 4: case 5:
                    // top, integer, float, double, long, null – no extra data
                    break;
                default:
                    throw new IllegalArgumentException("Unknown verification type tag: " + tag);
            }
        } catch (java.io.IOException e) {
            throw new RuntimeException("Failed to write verification type info", e);
        }
    }
}

