@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }

    // Null values are allowed and simply return null
    if (value == null) {
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return value;
    }

    // String conversion: must be a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert String to Character: length != 1");
        }
    }

    // Number conversion: cast to int and check range
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new Exception("Number value out of char range");
        }
        return (char) intVal;
    }

    // Fallback: use toString and ensure single character
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    // If none of the above, conversion is not possible
    throw new Exception("Cannot convert value to java.lang.Character");
}

