public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure we start with an odd number
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++;
    }
    // Determine search limit for 11% rule
    long limit = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        long temp = (long) Math.ceil(desiredCapacity * 1.11);
        if (temp > Integer.MAX_VALUE) {
            limit = Integer.MAX_VALUE;
        } else {
            limit = temp;
        }
    }
    while (candidate <= limit) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
    // If not found within limit, continue searching beyond limit
    while (candidate > 0) { // candidate will not overflow because we stop at Integer.MAX_VALUE
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
    }
    // Fallback (should never reach here)
    return Integer.MAX_VALUE;
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 5; i <= sqrtN; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

