private static int digitValue(final char c) {
    // Numeric digits
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // Uppercase alphabetic digits
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    // Lowercase alphabetic digits
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    // Non-ASCII or unsupported characters
    return -1;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if(jsonObject == null){
        return content;
    }
    try{
        for(Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
            String key = entry.getKey();
            JsonElement elem = entry.getValue();
            Object value = null;
            if(elem == null || elem.isJsonNull()){
                value = null;
            } else if(elem.isJsonPrimitive()){
                JsonPrimitive prim = elem.getAsJsonPrimitive();
                if(prim.isBoolean()){
                    value = prim.getAsBoolean();
                } else if(prim.isNumber()){
                    Number num = prim.getAsNumber();
                    if(num.doubleValue() == num.longValue()){
                        if(num.longValue() <= Integer.MAX_VALUE && num.longValue() >= Integer.MIN_VALUE){
                            value = num.intValue();
                        } else {
                            value = num.longValue();
                        }
                    } else {
                        value = num.doubleValue();
                    }
                } else if(prim.isString()){
                    value = prim.getAsString();
                }
            } else if(elem.isJsonObject()){
                value = elem.getAsJsonObject();
            } else if(elem.isJsonArray()){
                value = elem.getAsJsonArray();
            }
            content.put(key, value);
        }
        if(jsonObject.has("ats") && !jsonObject.get("ats").isJsonNull()){
            content.put("ats", jsonObject.get("ats"));
        }
    } catch(Exception e){
        return new HashMap<>();
    }
    return content;
}

