public final byte[] toByteArray() {
    try {
        Object bufField = this.buffers; // field holding the buffers
        if (bufField == null) {
            return new byte[0];
        }

        java.util.List<?> bufferList = null;
        Object[] bufferArray = null;

        if (bufField instanceof java.util.List) {
            bufferList = (java.util.List<?>) bufField;
        } else if (bufField instanceof Object[]) {
            bufferArray = (Object[]) bufField;
        } else if (bufField instanceof byte[]) {
            bufferArray = new Object[]{bufField};
        } else {
            throw new IllegalStateException("Unsupported buffers field type: " + bufField.getClass());
        }

        long total = 0;
        if (bufferList != null) {
            for (Object buf : bufferList) {
                if (buf == null) continue;
                if (buf instanceof byte[]) {
                    total += ((byte[]) buf).length;
                } else if (buf instanceof java.nio.ByteBuffer) {
                    total += ((java.nio.ByteBuffer) buf).remaining();
                } else {
                    throw new IllegalStateException("Unsupported buffer element type: " + buf.getClass());
                }
                if (total > Integer.MAX_VALUE) {
                    throw new IllegalStateException("Total size exceeds maximum array length");
                }
            }
        } else if (bufferArray != null) {
            for (Object buf : bufferArray) {
                if (buf == null) continue;
                if (buf instanceof byte[]) {
                    total += ((byte[]) buf).length;
                } else if (buf instanceof java.nio.ByteBuffer) {
                    total += ((java.nio.ByteBuffer) buf).remaining();
                } else {
                    throw new IllegalStateException("Unsupported buffer element type: " + buf.getClass());
                }
                if (total > Integer.MAX_VALUE) {
                    throw new IllegalStateException("Total size exceeds maximum array length");
                }
            }
        }

        byte[] result = new byte[(int) total];
        int pos = 0;

        if (bufferList != null) {
            for (Object buf : bufferList) {
                if (buf == null) continue;
                if (buf instanceof byte[]) {
                    byte[] arr = (byte[]) buf;
                    System.arraycopy(arr, 0, result, pos, arr.length);
                    pos += arr.length;
                } else if (buf instanceof java.nio.ByteBuffer) {
                    java.nio.ByteBuffer bb = (java.nio.ByteBuffer) buf;
                    int len = bb.remaining();
                    bb.get(result, pos, len);
                    pos += len;
                }
            }
        } else if (bufferArray != null) {
            for (Object buf : bufferArray) {
                if (buf == null) continue;
                if (buf instanceof byte[]) {
                    byte[] arr = (byte[]) buf;
                    System.arraycopy(arr, 0, result, pos, arr.length);
                    pos += arr.length;
                } else if (buf instanceof java.nio.ByteBuffer) {
                    java.nio.ByteBuffer bb = (java.nio.ByteBuffer) buf;
                    int len = bb.remaining();
                    bb.get(result, pos, len);
                    pos += len;
                }
            }
        }

        return result;
    } catch (Exception e) {
        throw new IllegalStateException("Failed to convert buffers to byte array", e);
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                throw new IllegalArgumentException("Trailing backslash at end of string");
            }
            char next = str.charAt(i + 1);
            // Handle escaped backslash
            if (next == '\\') {
                sb.append('\\');
                i++; // skip the escaped backslash
                continue;
            }
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 6 > len) {
                        throw new IllegalArgumentException("Incomplete Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape sequence: \\u" + hex);
                    }
                    i += 5; // skip 'u' and 4 hex digits
                    break;
                default:
                    // Unknown escape sequence: keep as is or throw exception
                    throw new IllegalArgumentException("Unknown escape sequence: \\" + next);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

