        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }
    if (!array.getClass().isArray()) {
        throw new IllegalArgumentException("Provided object is not an array");
    }
    int oldLen = java.lang.reflect.Array.getLength(array);
    Class<?> componentType = array.getClass().getComponentType();
    Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLen + 1);
    System.arraycopy(array, 0, newArray, 0, oldLen);
    return newArray;
}

