protected int removeUnusedNodes() {
    int removedCount = 0;
    try {
        // Assume there is a field named 'root' of type Category
        if (root == null) {
            return 0;
        }
        java.util.Deque<java.util.Iterator<Category>> stack = new java.util.ArrayDeque<>();
        java.util.List<Category> rootChildren = root.getChildren();
        if (rootChildren != null) {
            stack.push(rootChildren.iterator());
        }
        while (!stack.isEmpty()) {
            java.util.Iterator<Category> it = stack.peek();
            if (!it.hasNext()) {
                stack.pop();
                continue;
            }
            Category child = it.next();
            if (child == null) {
                continue;
            }
            if (!child.isActive()) {
                it.remove();
                removedCount++;
            } else {
                java.util.List<Category> children = child.getChildren();
                if (children != null && !children.isEmpty()) {
                    stack.push(children.iterator());
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return -1 to indicate failure
        return -1;
    }
    return removedCount;
}

