final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Validate input parameters
    if (constantPoolEntryIndex <= 0) {
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }
    // Assume classFileBuffer and constantPoolOffsets are fields of the enclosing class
    if (classFileBuffer == null) {
        throw new IllegalStateException("classFileBuffer is not initialized");
    }
    if (constantPoolOffsets == null) {
        throw new IllegalStateException("constantPoolOffsets is not initialized");
    }
    if (constantPoolEntryIndex >= constantPoolOffsets.length) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }

    final int entryOffset = constantPoolOffsets[constantPoolEntryIndex];
    if (entryOffset < 0 || entryOffset + 3 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry offset");
    }

    // Read the tag byte
    final int tag = classFileBuffer[entryOffset] & 0xFF;
    if (tag != 1) { // 1 = CONSTANT_Utf8
        throw new IllegalArgumentException("Constant pool entry is not a CONSTANT_Utf8");
    }

    // Read the length (u2)
    final int length = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8)
                     | (classFileBuffer[entryOffset + 2] & 0xFF);

    if (length < 0) {
        throw new IllegalArgumentException("Negative length for CONSTANT_Utf8");
    }
    if (length > charBuffer.length) {
        throw new IllegalArgumentException("charBuffer too small for the UTF-8 string");
    }

    // Ensure the byte array contains enough data
    if (entryOffset + 3 + length > classFileBuffer.length) {
        throw new IllegalArgumentException("classFileBuffer does not contain enough bytes for the UTF-8 string");
    }

    // Construct the string using UTF-8 encoding
    final String utf8String = new String(classFileBuffer, entryOffset + 3, length,
                                         java.nio.charset.StandardCharsets.UTF_8);

    // Copy the characters into the provided buffer
    utf8String.getChars(0, utf8String.length(), charBuffer, 0);

    // Return a new String backed by the charBuffer (to avoid exposing the buffer)
    return new String(charBuffer, 0, utf8String.length());
}

