private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    if (dir != 0 && dir != 1) {
        throw new IllegalArgumentException("Direction must be 0 (clockwise) or 1 (counter‑clockwise)");
    }
    try {
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
        // If the start node is already the stop node, return immediately
        if (start.equals(stop)) {
            return circ;
        }
        while (!circ.getNode().equals(stop)) {
            if (predicate.test(circ.getNode())) {
                break;
            }
            circ.next();
        }
        return circ;
    } catch (Exception e) {
        // In case of any runtime issue, return a circulator positioned at the stop node
        return new OuterFaceCirculator(stop, dir);
    }
}

