public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // If nothing to put, just return
    if (byteLength == 0) {
        return this;
    }
    // Validate offset and array bounds if array is provided
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
        }
    } else {
        // If array is null, we will just insert nullbytes (zeros)
        // No need to validate offset
    }

    // Ensure we don't overflow when computing new length
    if (byteLength > Integer.MAX_VALUE - this.length) {
        throw new IllegalArgumentException("Resulting length would overflow");
    }
    int newLength = this.length + byteLength;

    // Ensure capacity
    if (this.buffer == null) {
        // Allocate new buffer
        int capacity = Math.max(16, newLength);
        this.buffer = new byte[capacity];
    } else if (this.buffer.length < newLength) {
        int newCapacity = Math.max(this.buffer.length * 2, newLength);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.length);
        this.buffer = newBuffer;
    }

    // Copy bytes or fill zeros
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, this.buffer, this.length, byteLength);
    } else {
        // Fill with zeros (nullbytes)
        java.util.Arrays.fill(this.buffer, this.length, newLength, (byte) 0);
    }

    // Update length
    this.length = newLength;
    return this;
}

