private void check(String modelName) throws IllegalStateException {
    if (modelName == null || modelName.trim().isEmpty()) {
        throw new IllegalArgumentException("modelName must not be null or empty");
    }
    try {
        // Retrieve sharding key indices for the given model
        java.util.List<Integer> indices = getShardingKeyIndices(modelName);
        if (indices == null || indices.isEmpty()) {
            throw new IllegalStateException("No sharding key indices found for model: " + modelName);
        }
        // Sort indices to ensure order
        java.util.List<Integer> sorted = new java.util.ArrayList<>(indices);
        java.util.Collections.sort(sorted);
        // Check continuity
        for (int i = 1; i < sorted.size(); i++) {
            if (sorted.get(i) != sorted.get(i - 1) + 1) {
                throw new IllegalStateException("Sharding key indices for model " + modelName + " are not continuous: " + sorted);
            }
        }
    } catch (IllegalStateException e) {
        throw e;
    } catch (Exception e) {
        throw new IllegalStateException("Failed to check sharding key indices for model: " + modelName, e);
    }
}

