        return 0.0;
    }
    for (V target : v) {
        if (target == null) {
            continue;
        }
        for (Map.Entry<V, List<Edge<V>>> entry : adjacencyList.entrySet()) {
            List<Edge<V>> edges = entry.getValue();
            if (edges == null) {
                continue;
            }
            for (Edge<V> e : edges) {
                if (e == null) {
