                if (target.equals(e.getTarget())) {
                    sum += e.getWeight();
                }
            }
        }
    }
    return sum;
}

public int compare(Object aObj1, Object aObj2) {
    try {
        // If both references are identical (including both null), they are equal
        if (aObj1 == aObj2) {
            return 0;
        }
        // Null handling: null is considered less than any non‑null value
        if (aObj1 == null) {
            return -1;
        }
        if (aObj2 == null) {
            return 1;
        }
        // Both objects are non‑null. Attempt to compare them if they implement Comparable
        if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
            @SuppressWarnings("unchecked")
            Comparable<Object> comp = (Comparable<Object>) aObj1;
            return comp.compareTo(aObj2);
        }
        // If either object does not implement Comparable, comparison is not possible
        throw new IllegalArgumentException("Both objects must implement Comparable");
    } catch (ClassCastException e) {
        // Thrown when the two objects are not mutually comparable
        throw new IllegalArgumentException("Objects are not mutually comparable", e);
    } catch (Exception e) {
        // Wrap any other unexpected exception
        throw new RuntimeException("Comparison failed", e);
    }
}

