private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // Escape sequence
        if (i + 1 >= len) {
            throw new IllegalArgumentException("Trailing backslash at end of input");
        }
        char next = input.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'v':
                sb.append('\u000B'); // vertical tab
                i++;
                break;
            case '0':
                sb.append('\0');
                i++;
                break;
            case 'x':
                if (i + 3 >= len) {
                    throw new IllegalArgumentException("Incomplete \\x escape sequence");
                }
                String hex2 = input.substring(i + 2, i + 4);
                try {
                    int val2 = Integer.parseInt(hex2, 16);
                    sb.append((char) val2);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid hex digits in \\x escape: " + hex2, e);
                }
                i += 3;
                break;
            case 'u':
                if (i + 5 >= len) {
                    throw new IllegalArgumentException("Incomplete \\u escape sequence");
                }
                String hex4 = input.substring(i + 2, i + 6);
                try {
                    int val4 = Integer.parseInt(hex4, 16);
                    sb.append((char) val4);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid hex digits in \\u escape: " + hex4, e);
                }
                i += 5;
                break;
            case 'U':
                if (i + 9 >= len) {
                    throw new IllegalArgumentException("Incomplete \\U escape sequence");
                }
                String hex8 = input.substring(i + 2, i + 10);
                try {
                    int val8 = Integer.parseInt(hex8, 16);
                    sb.append(Character.toChars(val8));
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid hex digits in \\U escape: " + hex8, e);
                }
                i += 9;
                break;
            default:
                // Any other character is escaped literally
                sb.append(next);
                i++;
                break;
        }
    }
    return sb.toString();
}

