        return null;
    }
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        // Nothing to move if the minimum label is already 0
        return;
    }
    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new java.util.HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }
    for (Integer v : minBucket) {
        if (v == null) {
            continue;
        }
        if (v < 0 || v >= labels.size()) {
            // Skip invalid vertex indices
            continue;
        }
        zeroBucket.add(v);
        labels.set(v, 0);
    }
    minBucket.clear();
}

