private void pop(final int elements) {
    if (elements <= 0) {
        throw new IllegalArgumentException("Number of elements to pop must be positive");
    }
    if (outputFrameStack == null) {
        throw new IllegalStateException("Output frame stack is not initialized");
    }
    if (elements > outputFrameStack.size()) {
        throw new IllegalStateException("Attempting to pop " + elements + " elements, but stack only contains " + outputFrameStack.size());
    }
    try {
        for (int i = 0; i < elements; i++) {
            outputFrameStack.pop();
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to pop elements from output frame stack", e);
    }
}

