private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("node cannot be null");
    }
    // If node is not part of this list, return false
    if (node.prev == null && node.next == null && node != head && node != tail) {
        return false;
    }
    try {
        if (node == head) {
            head = node.next;
            if (head != null) {
                head.prev = null;
            } else {
                tail = null;
            }
        } else if (node == tail) {
            tail = node.prev;
            if (tail != null) {
                tail.next = null;
            } else {
                head = null;
            }
        } else {
            // Middle node
            if (node.prev != null) {
                node.prev.next = node.next;
            }
            if (node.next != null) {
                node.next.prev = node.prev;
            }
        }
        // Clean up the removed node
        node.next = null;
        node.prev = null;
        // Optional: clear data to help GC
        // node.data = null;
        if (size > 0) {
            size--;
        }
        return true;
    } catch (Exception e) {
        return false;
    }
}

public List<SequenceRange> buildSequenceRanges(){
    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    try {
        if (profiles == null || profiles.isEmpty()) {
            return ranges;
        }
        for (Profile profile : profiles) {
            if (profile == null) continue;
            java.util.List<Segment> segments = profile.getSegments();
            if (segments == null) continue;
            for (Segment seg : segments) {
                if (seg == null) continue;
                int start = seg.getStart();
                int end = seg.getEnd();
                ranges.add(new SequenceRange(start, end));
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to build sequence ranges", e);
    }
    return ranges;
}

