private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int n = bounds.size();
    int[] suffixArray = new int[n];
    long cumulative = 0L;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds list contains null element at index " + i);
        }
        cumulative += val;
        suffixArray[i] = (int) cumulative;
    }
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(suffixArray[i]);
    }
    long totalSum = cumulative;
    return new Pair<>(suffix, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array must not be null");
    }
    if (from < 0 || to >= arr.length) {
        throw new IndexOutOfBoundsException(
            "Index out of bounds: from=" + from + ", to=" + to + ", length=" + arr.length);
    }
    if (from > to) {
        throw new IllegalArgumentException("from index must be less than or equal to to index");
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Validate input
    if (list == null) {
        throw new IllegalArgumentException("Source list cannot be null");
    }
    // No-op if the source is this list
    if (list == this) {
        return;
    }
    // No-op if the source list is empty
    if (list.size == 0) {
        return;
    }

    // Detach the source list's node chain
    ListNode<E> srcFirst = list.head;
    ListNode<E> srcLast  = list.tail;

    // Attach the chain to this list
    if (this.size == 0) {
        // This list is empty – simply adopt the source chain
        this.head = srcFirst;
        this.tail = srcLast;
    } else {
        // Link the tail of this list to the head of the source chain
        this.tail.next = srcFirst;
        srcFirst.prev = this.tail;
        this.tail = srcLast;
    }

    // Update sizes
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && prefix == null) {
        return true;
    }
    // If only one is null, no match
    if (str == null || prefix == null) {
        return false;
    }
    // If ignoreCase is true, use regionMatches with ignoreCase flag
    if (ignoreCase) {
        // regionMatches handles length checks internally
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    // Otherwise use the standard startsWith
    return str.startsWith(prefix);
}

