public void putAllWriteable(BeanMap map){
    if (map == null) {
        throw new IllegalArgumentException("map cannot be null");
    }
    java.beans.PropertyDescriptor[] srcDescs = map.getPropertyDescriptors();
    java.beans.PropertyDescriptor[] tgtDescs = this.getPropertyDescriptors();
    if (srcDescs == null || tgtDescs == null) {
        return;
    }
    for (Object keyObj : map.keySet()) {
        if (!(keyObj instanceof String)) {
            continue;
        }
        String key = (String) keyObj;
        java.beans.PropertyDescriptor srcDesc = null;
        for (java.beans.PropertyDescriptor pd : srcDescs) {
            if (pd.getName().equals(key)) {
                srcDesc = pd;
                break;
            }
        }
        if (srcDesc == null) {
            continue;
        }
        // Only consider properties that are both readable and writable in the source
        if (srcDesc.getReadMethod() == null || srcDesc.getWriteMethod() == null) {
            continue;
        }
        Object value;
        try {
            value = map.getProperty(key);
        } catch (Exception e) {
            continue; // skip if value cannot be retrieved
        }
        java.beans.PropertyDescriptor tgtDesc = null;
        for (java.beans.PropertyDescriptor pd : tgtDescs) {
            if (pd.getName().equals(key)) {
                tgtDesc = pd;
                break;
            }
        }
        if (tgtDesc == null || tgtDesc.getWriteMethod() == null) {
            continue; // target property not writable
        }
        try {
            this.setProperty(key, value);
        } catch (Exception e) {
            // ignore failures to set the property
        }
    }
}

