private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(){
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparators = new ArrayList<>();
    try {
        if (graph == null) {
            return globalSeparators;
        }
        Collection<E> edges = graph.getEdges();
        if (edges == null) {
            return globalSeparators;
        }
        for (E edge : edges) {
            if (edge == null) {
                continue;
            }
            // Assume the graph provides a method to retrieve minimal separators for a given edge.
            // The method is expected to return a list of separators, where each separator is a list of
            // vertex pairs (represented as Pair<Integer,Integer>).
            List<List<Pair<Integer,Integer>>> separators = null;
            try {
                separators = graph.getMinimalSeparators(edge);
            } catch (Exception inner) {
                // If the graph does not provide this method or an error occurs, skip this edge.
                continue;
            }
            if (separators == null) {
                continue;
            }
            for (List<Pair<Integer,Integer>> separator : separators) {
                if (separator == null) {
                    continue;
                }
                globalSeparators.add(new Pair<>(separator, edge));
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime exception, return the separators collected so far.
        // Logging can be added here if a logger is available.
    }
    return globalSeparators;
}

