public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    try {
        SwingUtilities.invokeLater(() -> {
            // Clear previous selection and select the desired row
            table.clearSelection();
            table.setRowSelectionInterval(row, row);
            // Scroll to make the row visible
            Rectangle rect = table.getCellRect(row, 0, true);
            if (rect != null) {
                table.scrollRectToVisible(rect);
            }
            // Delay repaint to allow the table to finish painting the new selection
            Timer repaintTimer = new Timer(50, e -> table.repaint());
            repaintTimer.setRepeats(false);
            repaintTimer.start();
        });
    } catch (Exception e) {
        // Log or handle exception as needed
    }
}

public ByteVector putInt(final int intValue){
    try {
        int required = position + 4;
        if (buffer == null) {
            buffer = new byte[Math.max(16, required)];
        } else if (required > buffer.length) {
            int newCap = Math.max(buffer.length * 2, required);
            byte[] newBuf = new byte[newCap];
            System.arraycopy(buffer, 0, newBuf, 0, buffer.length);
            buffer = newBuf;
        }
        buffer[position++] = (byte)(intValue >>> 24);
        buffer[position++] = (byte)(intValue >>> 16);
        buffer[position++] = (byte)(intValue >>> 8);
        buffer[position++] = (byte)(intValue);
        return this;
    } catch (Exception e) {
        throw new RuntimeException("Failed to put int into ByteVector", e);
    }
}

