private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // Empty or single-vertex subgraph is trivially a clique
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < size; i++) {
        @SuppressWarnings("unchecked")
        V vi = (V) arr[i];
        if (vi == null) {
            throw new IllegalArgumentException("Vertices set contains null element");
        }
        for (int j = i + 1; j < size; j++) {
            @SuppressWarnings("unchecked")
            V vj = (V) arr[j];
            if (vj == null) {
                throw new IllegalArgumentException("Vertices set contains null element");
            }
            try {
                if (!graph.containsEdge(vi, vj)) {
                    return false;
                }
            } catch (IllegalArgumentException e) {
                // One of the vertices is not part of the graph
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    // Separate non-null keys for sorting
    List<K> nonNullKeys = new ArrayList<>();
    for (K key : keys) {
        if (key != null) {
            nonNullKeys.add(key);
        }
    }
    // Sort the non-null keys; they must be comparable
    try {
        Collections.sort(nonNullKeys);
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("All keys must be comparable", e);
    }
    // For each original key, find the maximum lower bound index
    for (K key : keys) {
        if (key == null) {
            result.add(-1);
            continue;
        }
        int index;
        try {
            index = Collections.binarySearch(nonNullKeys, key);
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("Key is not comparable to the list", e);
        }
        if (index < 0) {
            // Should not happen as key is from the original list
            result.add(-1);
        } else {
            int lowerIndex = index - 1;
            result.add(lowerIndex);
        }
    }
    return result;
}

