public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (path.isEmpty()) {
        throw new IllegalArgumentException("path cannot be empty");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    try {
        boolean isAbsolute = path.startsWith("/");
        // Split the base path into components, ignoring empty parts
        String[] baseParts = path.split("/");
        java.util.List<String> stack = new java.util.ArrayList<>();
        for (String part : baseParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                } else if (!isAbsolute) {
                    // For a relative base path, preserve leading ".."
                    stack.add("..");
                }
            } else {
                stack.add(part);
            }
        }

        // Process the relative path components
        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                } else if (!isAbsolute) {
                    stack.add("..");
                }
            } else {
                stack.add(part);
            }
        }

        // Build the resulting path
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        if (isAbsolute) {
            sb.append("/");
        }
        for (int i = 0; i < stack.size(); i++) {
            if (i > 0) {
                sb.append("/");
            }
            sb.append(stack.get(i));
        }

        // If the result is empty and the original path was absolute, return "/"
        if (sb.length() == 0 && isAbsolute) {
            return "/";
        }

        return sb.toString();
    } catch (Exception e) {
        // Wrap any unexpected exception in a RuntimeException
        throw new RuntimeException("Error applying relative path", e);
    }
}

public static int indexOf(String str, String searchStr) {
    if (str == null || searchStr == null) {
        return -1;
    }
    try {
        return str.indexOf(searchStr);
    } catch (Exception e) {
        // Unexpected exception, return -1 to indicate not found
        return -1;
    }
}

static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return new String[0];
    }
    // Check if array is already a String[] and contains no nulls
    if (array instanceof String[]) {
        String[] strArray = (String[]) array;
        for (String s : strArray) {
            if (s == null) {
                // contains null, need to filter
                break;
            }
        }
        // If no null found, return original array
        boolean hasNull = false;
        for (String s : strArray) {
            if (s == null) {
                hasNull = true;
                break;
            }
        }
        if (!hasNull) {
            return strArray;
        }
    }

    java.util.List<String> list = new java.util.ArrayList<>(array.length);
    for (Object obj : array) {
        if (obj != null) {
            if (!(obj instanceof String)) {
                throw new IllegalArgumentException("Array contains non-String element: " + obj);
            }
            list.add((String) obj);
        }
    }
    return list.toArray(new String[0]);
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int sepIndex = indexOfLastSeparator(filename);
    if (sepIndex > dotIndex) {
        return -1;
    }
    return dotIndex;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        long currentTime = System.currentTimeMillis();
        // If the threshold is non-positive, consider it expired immediately
        if (expiredThreshold <= 0) {
            return true;
        }
        // Avoid negative difference when timestamp is in the future
        if (timestamp > currentTime) {
            return false;
        }
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, default to not expired
        return false;
    }
}

Edge edgeToNext() {
    if (previousNode == null || nextNode == null) {
        throw new IllegalStateException("Previous or next node is not set");
    }
    Node from = previousNode.isVirtual() ? previousNode.getRealNode() : previousNode;
    Node to   = nextNode.isVirtual()    ? nextNode.getRealNode()    : nextNode;
    if (from == null || to == null) {
        throw new IllegalStateException("Edge endpoints cannot be null");
    }
    return new Edge(from, to);
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Validate inputs
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();

    // Empty substring matches at any valid index
    if (subLen == 0) {
        return index >= 0 && index <= strLen;
    }

    // Index must be within bounds and enough space for the substring
    if (index < 0 || index > strLen - subLen) {
        return false;
    }

    // Compare characters
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (message == null) {
        message = "";
    }
    // Append a newline to separate log entries
    message += System.lineSeparator();
    // If there are no connected clients, nothing to do
    if (clientSockets == null) {
        return;
    }
    // Iterate over the client sockets, sending the message to each
    java.util.Iterator<java.net.Socket> iterator = clientSockets.iterator();
    while (iterator.hasNext()) {
        java.net.Socket socket = iterator.next();
        if (socket == null || socket.isClosed()) {
            iterator.remove();
            continue;
        }
        try {
            java.io.OutputStream out = socket.getOutputStream();
            out.write(message.getBytes("UTF-8"));
            out.flush();
        } catch (java.io.IOException e) {
            // Remove the socket from the collection on failure
            iterator.remove();
            // Log the error to standard error
            System.err.println("Failed to send log message to client: " + e.getMessage());
        }
    }
}

private void checkIfPackedField() throws IOException {
    // Determine the wire type from the current tag
    int wireType = currentTag & 0x7;
    // Wire type 2 corresponds to length-delimited fields
    if (wireType == 2) {
        // Assume this is a packed repeated field
        isPacked = true;
        // Read the length of the packed data
        int packedLength = input.readRawVarint32();
        // Record the end position of the packed field
        packedFieldEnd = input.getPosition() + packedLength;
    } else {
        isPacked = false;
    }
}

public int readTag() throws IOException {
    try {
        return readRawVarint32();
    } catch (java.io.EOFException e) {
        return 0;
    }
}

final ByteVector put11(final int byteValue1, final int byteValue2) {
    // Validate that the provided values are within the byte range.
    if (byteValue1 < -128 || byteValue1 > 127 || byteValue2 < -128 || byteValue2 > 127) {
        throw new IllegalArgumentException("byte values must be in the range -128..127");
    }
    // Append the two bytes to the vector.
    put((byte) byteValue1);
    put((byte) byteValue2);
    return this;
}

private String buildContentRange() {
    try {
        // Assume the class has fields: start, end, totalLength of type long
        if (start < 0 || end < 0 || totalLength <= 0) {
            throw new IllegalArgumentException("Invalid range values: start=" + start + ", end=" + end + ", totalLength=" + totalLength);
        }
        if (start > end) {
            throw new IllegalArgumentException("Start byte (" + start + ") is greater than end byte (" + end + ")");
        }
        return "bytes " + start + "-" + end + "/" + totalLength;
    } catch (Exception e) {
        // In case of any unexpected error, return null or an empty string
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Validate file
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new java.io.FileNotFoundException("File not found: " + file);
    }

    // Determine if we should filter by time ranges
    boolean filterByRange = timeRanges != null && !timeRanges.isEmpty();

    // Prepare result list
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();

    // Prepare reflection helpers
    java.lang.reflect.Method parseMethod = null;
    java.lang.reflect.Constructor<?> stringConstructor = null;
    try {
        // Try to find a static parse(String) method
        parseMethod = ThreadSnapshot.class.getMethod("parse", String.class);
        if (!java.lang.reflect.Modifier.isStatic(parseMethod.getModifiers())) {
            parseMethod = null;
        }
    } catch (NoSuchMethodException e) {
        // ignore
    }
    if (parseMethod == null) {
        try {
            // Try to find a constructor that takes a String
            stringConstructor = ThreadSnapshot.class.getConstructor(String.class);
        } catch (NoSuchMethodException e) {
            // ignore
        }
    }
    if (parseMethod == null && stringConstructor == null) {
        // Cannot parse snapshots
        throw new IllegalStateException("ThreadSnapshot must have a static parse(String) method or a String constructor");
    }

    // Prepare methods for time range and timestamp
    java.lang.reflect.Method getTimestampMethod = null;
    try {
        getTimestampMethod = ThreadSnapshot.class.getMethod("getTimestamp");
    } catch (NoSuchMethodException e) {
        // ignore
    }
    if (getTimestampMethod == null) {
        throw new IllegalStateException("ThreadSnapshot must have a getTimestamp() method");
    }

    java.lang.reflect.Method getStartTimeMethod = null;
    java.lang.reflect.Method getEndTimeMethod = null;
    if (filterByRange) {
        try {
            getStartTimeMethod = ProfileAnalyzeTimeRange.class.getMethod("getStartTime");
            getEndTimeMethod = ProfileAnalyzeTimeRange.class.getMethod("getEndTime");
        } catch (NoSuchMethodException e) {
            throw new IllegalStateException("ProfileAnalyzeTimeRange must have getStartTime() and getEndTime() methods");
        }
    }

    // Read file line by line
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            ThreadSnapshot snapshot = null;
            try {
                if (parseMethod != null) {
                    snapshot = (ThreadSnapshot) parseMethod.invoke(null, line);
                } else if (stringConstructor != null) {
                    snapshot = (ThreadSnapshot) stringConstructor.newInstance(line);
                }
            } catch (Exception e) {
                // Skip lines that cannot be parsed
                continue;
            }

            if (snapshot == null) {
                continue;
            }

            long timestamp;
            try {
                Object tsObj = getTimestampMethod.invoke(snapshot);
                if (tsObj instanceof Number) {
                    timestamp = ((Number) tsObj).longValue();
                } else {
                    continue; // invalid timestamp
                }
            } catch (Exception e) {
                continue; // skip if timestamp cannot be retrieved
            }

            boolean inRange = !filterByRange;
            if (filterByRange) {
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start, end;
                    try {
                        Object startObj = getStartTimeMethod.invoke(range);
                        Object endObj = getEndTimeMethod.invoke(range);
                        if (startObj instanceof Number && endObj instanceof Number) {
                            start = ((Number) startObj).longValue();
                            end = ((Number) endObj).longValue();
                        } else {
                            continue;
                        }
                    } catch (Exception e) {
                        continue;
                    }
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
                    }
                }
            }

            if (inRange) {
                result.add(snapshot);
            }
        }
    } catch (java.io.IOException e) {
        throw e;
    }

    return result;
}
